<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Struk #{{ $order->id }}</title><link rel="stylesheet" href="/app.css">@include('partials.pastel')<script src="/invoice.js" defer></script></head><body><main style="max-width:600px;margin:30px auto;padding:20px"><header><p>{{ $hotel->name }} @if($hotel->is_demo) · Data contoh @endif</p><h1>Pesanan #{{ $order->id }}</h1><p>{{ $order->order_type }} · {{ $order->table_label ?? $order->customer }}<br>{{ \Carbon\Carbon::parse($order->created_at,'UTC')->timezone($hotel->timezone)->format('d/m/Y H:i') }}</p></header><section class="panel"><h2>Rincian pesanan</h2><table><thead><tr><th>Menu</th><th>Jumlah</th></tr></thead><tbody>@foreach(json_decode($order->items,true) as $line)<tr><td>{{ $line['quantity'] }} × {{ $line['name'] }}</td><td>Rp {{ number_format($line['price']*$line['quantity'],0,',','.') }}</td></tr>@endforeach<tr><td>Diskon</td><td>− Rp {{ number_format($order->discount,0,',','.') }}</td></tr><tr><td>Service</td><td>Rp {{ number_format($order->service,0,',','.') }}</td></tr><tr><td>Pajak</td><td>Rp {{ number_format($order->tax,0,',','.') }}</td></tr><tr><td><strong>Total</strong></td><td>Rp {{ number_format($order->total,0,',','.') }}</td></tr></tbody></table><p>Status pembayaran: <strong>{{ ['paid'=>'Lunas','room'=>'Ditagihkan ke kamar','unpaid'=>'Belum dibayar'][$order->payment_status] }}</strong></p>@if($order->payment_status==='paid')<p>{{ $order->payment_method }}<br>Diterima: Rp {{ number_format($order->tendered,0,',','.') }}<br>Kembalian: Rp {{ number_format($order->tendered-$order->total,0,',','.') }}</p>@endif<p>{{ $order->notes }}</p></section><footer><p class="muted">Dokumen operasional, bukan faktur pajak.</p><div class="actions"><a href="/#food">Kembali ke restoran</a><button class="primary" type="button" id="print-invoice">Cetak struk</button></div></footer></main></body></html>
